import{_ as r,C as o,o as s,c as i,a2 as t,E as a}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"General","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/general.md","filePath":"configuration/general.md","lastUpdated":1789411447000}'),l={name:"configuration/general.md"};function h(d,e,p,c,g,u){const n=o("ImagePopup");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>The <strong>General</strong> screen turns the marketplace on, sets the commission the store keeps from seller sales, and switches subscription plans on or off.</p><p>Go to <strong>Configure &gt;&gt; Marketplace &gt;&gt; General</strong>.</p><h2 id="general-1" tabindex="-1">General <a class="header-anchor" href="#general-1" aria-label="Permalink to &quot;General&quot;">​</a></h2>',5)),a(n,{src:"/images/configuration/general-general.png",alt:"General section of the Marketplace General settings"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>Switches the whole marketplace on or off for the channel. See <a href="./overview#turning-the-marketplace-off">Turning the marketplace off</a>.</td></tr><tr><td><strong>Admin Commission Percentage</strong></td><td>The commission taken from every seller sale, between 1 and 100. A seller with their own rate uses that instead. The rate is fixed on each order when it is placed. See <a href="./../payments/commission-management">Commission</a>.</td></tr><tr><td><strong>Seller Panel Logo</strong></td><td>The logo in the Seller Panel header. Upload a square image for the best fit. Without one, the Bagisto icon is shown.</td></tr></tbody></table><h3 id="set-the-commission" tabindex="-1">Set the commission <a class="header-anchor" href="#set-the-commission" aria-label="Permalink to &quot;Set the commission&quot;">​</a></h3><ol><li>Go to <strong>Configure &gt;&gt; Marketplace &gt;&gt; General</strong>.</li><li>In the <strong>General</strong> section, enter the <strong>Admin Commission Percentage</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The new rate applies to orders placed from now on. Orders already placed keep the rate they were placed with.</p><h2 id="subscription" tabindex="-1">Subscription <a class="header-anchor" href="#subscription" aria-label="Permalink to &quot;Subscription&quot;">​</a></h2><p>Subscription plans let you charge sellers for selling on the marketplace and limit what each plan includes.</p>',6)),a(n,{src:"/images/configuration/general-subscription.png",alt:"Subscription and Module Information sections"}),e[2]||(e[2]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Subscription Plans</strong></td><td>Turns subscription plans on for the channel.</td></tr><tr><td><strong>Subscription Terms and Conditions</strong></td><td>The terms sellers must accept before they buy a plan. It appears once <strong>Subscription Plans</strong> is on, is required, and is saved for each language.</td></tr></tbody></table><h3 id="turn-on-subscription-plans" tabindex="-1">Turn on subscription plans <a class="header-anchor" href="#turn-on-subscription-plans" aria-label="Permalink to &quot;Turn on subscription plans&quot;">​</a></h3><ol><li>Go to <strong>Configure &gt;&gt; Marketplace &gt;&gt; General</strong>.</li><li>In the <strong>Subscription</strong> section, switch <strong>Subscription Plans</strong> on. The <strong>Subscription Terms and Conditions</strong> field appears.</li><li>Enter the terms your sellers agree to.</li><li>Click <strong>Save Configuration</strong>.</li></ol><h3 id="what-changes-when-plans-are-on" tabindex="-1">What changes when plans are on <a class="header-anchor" href="#what-changes-when-plans-are-on" aria-label="Permalink to &quot;What changes when plans are on&quot;">​</a></h3><ul><li><strong>Marketplace &gt;&gt; Subscription Plans</strong> appears in the admin panel, and <strong>Plans</strong> appears in the Seller Panel.</li><li>A seller needs an active plan. Until they have one, they can only open their profile and the plans page. Their products are hidden from the storefront, their shop page can&#39;t be opened, and they are left out of the featured sellers.</li><li>What sellers and their team can do is limited to the permissions of their plan.</li><li>Reminder emails go out before a plan ends, ended plans are marked expired, and seller account health is refreshed every day. These run on the store&#39;s scheduler, so ask whoever manages your server to make sure it is running.</li></ul><p>See <a href="./../subscriptions/seller-subscription-management">Plans &amp; Subscriptions</a> to create plans.</p><h2 id="module-information" tabindex="-1">Module Information <a class="header-anchor" href="#module-information" aria-label="Permalink to &quot;Module Information&quot;">​</a></h2><p>Shows the version of the marketplace module installed on your store. There is nothing to change here.</p>',8))])}const b=r(l,[["render",h]]);export{f as __pageData,b as default};
